// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Give user some ether
        vm.deal(address(0x123), 2 ether);

        // Set block.timestamp explicitly
        vm.warp(1000);

        // User puts 1 ether with _unlockTime = 500 (before current time)
        vm.prank(address(0x123));
        c.Put{value: 1 ether}(500);

        // Now check acc.unlockTime for user
        (uint unlockTime, uint balance) = c.Acc(address(0x123));

        // Reference: unlockTime should be block.timestamp (1000) because 500 <= 1000
        // Buggy: unlockTime is 500 because it is set directly
        // So we assert unlockTime == 1000 (true for reference, false for buggy)
        assertEq(unlockTime, 1000);
    }
}

