pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x123);
        // Give alice 1 ether
        vm.deal(alice, 1 ether);
        // Set unlock time in the past so Collect can be called
        vm.warp(1000);
        // alice calls Put with unlockTime < current time, depositing 1 ether
        vm.prank(alice);
        c.Put{value: 1 ether}(500);
        // Now alice tries to collect 0.5 ether, but recipient (this contract) will reject the call
        // The reference version does NOT subtract if the call fails; the bug does subtract first
        bool ok;
        try c.Collect(0.5 ether) { ok = true; } catch { ok = false; }
        // The call should revert because the external call to address(this) fails (no receive/fallback)
        // In the reference, the balance remains 1 ether (since subtraction only on success)
        // In the buggy version, balance becomes 0.5 ether despite revert
        // Thus we assert that c.Acc(alice).balance == 1 ether
        (uint unlockTime, uint balance) = c.Acc(alice);
        assertEq(balance, 1 ether);
    }
}

