pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up scenario: user Alice has initial balance 0, MinSum is 1 ether by default
        address alice = address(0x123);
        vm.deal(alice, 0);

        // Alice calls Put to set unlockTime to future so she can call Collect later
        vm.warp(100);  // block.timestamp = 100
        vm.prank(alice);
        c.Put(200);    // unlockTime = 200, balance = 0 (msg.value = 0)

        // Advance time past unlock
        vm.warp(300);

        // Now try Collect(0.1 ether = 0.1e18). In reference, balance < MinSum so Collect has revert guard.
        // In buggy version, guard is removed, so call succeeds but sub_uint256(0, 0.1e18) underflows => revert.
        // For the buggy version, it's ambiguous; we check that Collect reverts.
        // We'll catch the revert and assert it happens.
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 0.1 ether));
        assertTrue(!ok);  // Both versions revert: reference due to balance < MinSum check, buggy due to unsafe subtraction
    }
}

