contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: give the contract some ether so it can hold balance
        address alice = address(0x123);
        vm.deal(alice, 5 ether);
        // Alice deposits 3 ether into the contract
        vm.prank(alice);
        c.Put{value: 3 ether}(0);
        // Advance time past the unlock (which was set to block.timestamp at deposit)
        vm.warp(block.timestamp + 1 days);
        // Now Alice attempts to collect 4 ether, but her balance is only 3.
        // Reference version: the condition acc.balance>=_am fails (3 >= 4 false) so the if block is skipped -> no revert, nothing happens.
        // Buggy version: the condition only checks block.timestamp > acc.unlockTime (true), so it proceeds to call and then subtracts 4 from 3 -> panic.
