pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deploy a contract that rejects direct Ether transfers to trigger call failure
        address rejector = address(new Rejector());

        // Fund the rejector so it can call Collect
        vm.deal(rejector, 5 ether);

        // Set up: rejector puts Ether into the contract
        vm.prank(rejector);
        c.Put{value: 3 ether}(block.timestamp + 100);

        // Warp past unlock time
        vm.warp(block.timestamp + 200);

        // Now rejector tries to Collect; the external call to rejector will fail because Rejector's receive() reverts
        vm.prank(rejector);
        bool ok;
        try c.Collect(2 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference (correct) version, the call fails, so balance remains unchanged (3 ether).
        // In the buggy version, the else branch deducts balance (to 1 ether).
        // We assert that the balance is still 3 ether — this passes on reference, fails on buggy.
        assertEq(c.Acc(rejector).balance, 3 ether);
    }
}

contract Rejector {
    fallback() external payable {
        revert("rejecting");
    }
    receive() external payable {
        revert("rejecting");
    }
}

