pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: Give the contract some ether for the Collect call
        vm.deal(address(c), 2 ether);
        // Scenario: actor calls Put to get a balance >= MinSum
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.Put{value: 2 ether}(0);

        // Warp past unlockTime (unlockTime set to block.timestamp in Put)
        vm.warp(block.timestamp + 1);

        // Now Collect 1 ether
        vm.prank(actor);
        c.Collect(1 ether);

        // In the reference version, balance becomes 1 ether.
        // In the bug version, balance becomes 3 ether (2 + 1 added).
        uint256 expectedBalance;
        {
            bool ok;
            try this.getBalance(address(c), actor) returns (uint256 bal) {
                expectedBalance = bal;
                ok = true;
            } catch {
                ok = false;
            }
            if (!ok) {
                // fallback if getter fails
                expectedBalance = 0;
            }
        }
        // Actually we just read c.Acc directly
        (uint unlockTime, uint bal) = c.Acc(actor);
        assertEq(bal, 1 ether);
    }

    function getBalance(address cAddr, address user) external view returns (uint256) {
        (uint unlockTime, uint bal) = C(cAddr).Acc(user);
        return bal;
    }
}

